-- SV2-GRF-01: canonical knowledge graph entities and typed relations.
-- Additive and idempotent. Nothing reads these tables yet; vault metadata stays
-- the source and the graph is rebuilt from it. The seed block is generated by
-- app.graph.seed_sql() in brain-api; a test fails when the two differ.

CREATE TABLE IF NOT EXISTS graph_entity_kinds (
    kind text PRIMARY KEY
);

CREATE TABLE IF NOT EXISTS graph_relation_types (
    relation text PRIMARY KEY,
    inverse text NOT NULL UNIQUE,
    is_symmetric boolean NOT NULL,
    allow_self boolean NOT NULL,
    requires_evidence boolean NOT NULL
);

CREATE TABLE IF NOT EXISTS graph_relation_pairs (
    relation text NOT NULL REFERENCES graph_relation_types (relation),
    source_kind text NOT NULL REFERENCES graph_entity_kinds (kind),
    target_kind text NOT NULL REFERENCES graph_entity_kinds (kind),
    PRIMARY KEY (relation, source_kind, target_kind)
);

CREATE TABLE IF NOT EXISTS graph_entities (
    id text PRIMARY KEY,
    kind text NOT NULL REFERENCES graph_entity_kinds (kind),
    brain text NOT NULL,
    project_id text NOT NULL,
    revision bigint NOT NULL CHECK (revision > 0),
    vault_ref text NOT NULL,
    UNIQUE (id, kind),
    CHECK (left(id, length(kind) + 1) = kind || ':' AND length(id) > length(kind) + 1)
);

CREATE TABLE IF NOT EXISTS graph_relations (
    relation text NOT NULL,
    source_id text NOT NULL,
    source_kind text NOT NULL,
    target_id text NOT NULL,
    target_kind text NOT NULL,
    status text NOT NULL CHECK (status IN ('suggested', 'verified', 'approved')),
    confidence text NOT NULL CHECK (confidence IN ('low', 'medium', 'high')),
    evidence text[] NOT NULL DEFAULT '{}',
    revision bigint NOT NULL CHECK (revision > 0),
    PRIMARY KEY (relation, source_id, target_id),
    FOREIGN KEY (source_id, source_kind) REFERENCES graph_entities (id, kind),
    FOREIGN KEY (target_id, target_kind) REFERENCES graph_entities (id, kind),
    FOREIGN KEY (relation, source_kind, target_kind) REFERENCES graph_relation_pairs
);

CREATE INDEX IF NOT EXISTS graph_relations_target ON graph_relations (target_id);

CREATE TABLE IF NOT EXISTS graph_relation_quarantine (
    id bigserial PRIMARY KEY,
    relation jsonb NOT NULL,
    reason text NOT NULL,
    recorded_at timestamptz NOT NULL DEFAULT now()
);

